package com.hmdp.ai.runtime.node;
import com.fasterxml.jackson.databind.ObjectMapper;import com.hmdp.ai.domain.workflow.*;import org.springframework.stereotype.Component;import java.util.*;import java.util.stream.Collectors;
@Component public class ParallelNodeExecutor implements NodeExecutor {private final ObjectMapper mapper;public ParallelNodeExecutor(ObjectMapper m){mapper=m;}public Set<WorkflowNodeType>supportedTypes(){return Collections.singleton(WorkflowNodeType.PARALLEL);}public NodeExecutionResult execute(NodeExecutionContext c){List<String>next=c.getOutgoingEdges().stream().map(WorkflowEdgeDefinition::getTargetNodeCode).collect(Collectors.toList());return next.isEmpty()?NodeExecutionResult.failure("PARALLEL_BRANCH_REQUIRED",false):NodeExecutionResult.success(mapper.valueToTree(next),next,null);}}
